mapper.select:
select *
from ai_conversation
where id=#{id}
and user_id=#{userId}
and status ='ACTIVE'

mapper.update:
update ai_conversation
set update_at=#{updateAt}
where id=#{id}
and user_id=#{userId}
and status='ACTIVE'

update set ai_conversation
set status='DELETED'
where id=#{id}
and user_id=#{userId}
and status='ACTIVE'
